import java.util.*;

class MyQueue {
    private Deque<Integer> in = new ArrayDeque<>();   // receives pushes
    private Deque<Integer> out = new ArrayDeque<>();  // serves the front

    public MyQueue() {
    }

    public void push(int x) {
        in.push(x);
    }

    public int pop() {
        shift();
        return out.pop();
    }

    public int peek() {
        shift();
        return out.peek();
    }

    public boolean empty() {
        return in.isEmpty() && out.isEmpty();
    }

    // move items only when out is empty: this reverses them into FIFO order
    private void shift() {
        if (out.isEmpty()) {
            while (!in.isEmpty()) out.push(in.pop());
        }
    }
}

