class MyQueue:
    def __init__(self):
        self.inp, self.out = [], []
    def push(self, x: int) -> None:
        self.inp.append(x)
    def _move(self):
        if not self.out:
            while self.inp: self.out.append(self.inp.pop())
    def pop(self) -> int:
        self._move(); return self.out.pop()
    def peek(self) -> int:
        self._move(); return self.out[-1]
    def empty(self) -> bool:
        return not self.inp and not self.out

